  "/pages/employee/stats.html": "\u003c!DOCTYPE html\u003e\r\n\u003chtml lang=\"fr\"\u003e\r\n\u003chead\u003e\r\n    \u003cmeta charset=\"UTF-8\"\u003e\r\n    \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\"\u003e\r\n    \u003ctitle\u003eStatistiques - Quai Antique\u003c/title\u003e\r\n\u003c/head\u003e\r\n\u003cbody\u003e\r\n    \u003cdiv class=\"hero-scene text-center text-white\"\u003e\r\n        \u003cdiv class=\"hero-scene-content\"\u003e\r\n            \u003ch1\u003e\u003ci class=\"bi bi-graph-up\"\u003e\u003c/i\u003e Statistiques de Consultation\u003c/h1\u003e\r\n            \u003cp class=\"lead\"\u003eAnalysez les plats et menus les plus populaires\u003c/p\u003e\r\n        \u003c/div\u003e\r\n    \u003c/div\u003e\r\n\r\n    \u003cdiv class=\"container mt-5\"\u003e\r\n       \r\n        \u003cdiv id=\"alertContainer\"\u003e\u003c/div\u003e\r\n\r\n       \r\n        \u003cdiv class=\"row mb-5\"\u003e\r\n            \u003cdiv class=\"col-md-6\"\u003e\r\n                \u003cdiv class=\"card text-white bg-primary\"\u003e\r\n                    \u003cdiv class=\"card-body\"\u003e\r\n                        \u003ch5 class=\"card-title\"\u003e\u003ci class=\"bi bi-eye-fill\"\u003e\u003c/i\u003e Vues totales - Plats\u003c/h5\u003e\r\n                        \u003ch2 id=\"totalFoodViews\" class=\"card-text\"\u003e-\u003c/h2\u003e\r\n                    \u003c/div\u003e\r\n                \u003c/div\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"col-md-6\"\u003e\r\n                \u003cdiv class=\"card text-white bg-success\"\u003e\r\n                    \u003cdiv class=\"card-body\"\u003e\r\n                        \u003ch5 class=\"card-title\"\u003e\u003ci class=\"bi bi-eye-fill\"\u003e\u003c/i\u003e Vues totales - Menus\u003c/h5\u003e\r\n                        \u003ch2 id=\"totalMenuViews\" class=\"card-text\"\u003e-\u003c/h2\u003e\r\n                    \u003c/div\u003e\r\n                \u003c/div\u003e\r\n            \u003c/div\u003e\r\n        \u003c/div\u003e\r\n\r\n     \r\n        \u003cdiv class=\"card mb-5 shadow\"\u003e\r\n            \u003cdiv class=\"card-header bg-primary text-white\"\u003e\r\n                \u003ch3 class=\"mb-0\"\u003e\u003ci class=\"bi bi-trophy-fill\"\u003e\u003c/i\u003e Top 10 des Plats les Plus Consultés\u003c/h3\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"card-body\"\u003e\r\n                \u003cdiv class=\"table-responsive\"\u003e\r\n                    \u003ctable class=\"table table-hover\"\u003e\r\n                        \u003cthead\u003e\r\n                            \u003ctr\u003e\r\n                                \u003cth\u003e#\u003c/th\u003e\r\n                                \u003cth\u003ePlat\u003c/th\u003e\r\n                                \u003cth\u003eConsultations\u003c/th\u003e\r\n                                \u003cth\u003eProgression\u003c/th\u003e\r\n                            \u003c/tr\u003e\r\n                        \u003c/thead\u003e\r\n                        \u003ctbody id=\"topFoodsTableBody\"\u003e\r\n                            \u003ctr\u003e\r\n                                \u003ctd colspan=\"4\" class=\"text-center\"\u003e\r\n                                    \u003cdiv class=\"spinner-border text-primary\" role=\"status\"\u003e\r\n                                        \u003cspan class=\"visually-hidden\"\u003eChargement...\u003c/span\u003e\r\n                                    \u003c/div\u003e\r\n                                \u003c/td\u003e\r\n                            \u003c/tr\u003e\r\n                        \u003c/tbody\u003e\r\n                    \u003c/table\u003e\r\n                \u003c/div\u003e\r\n            \u003c/div\u003e\r\n        \u003c/div\u003e\r\n\r\n       \r\n        \u003cdiv class=\"card mb-5 shadow\"\u003e\r\n            \u003cdiv class=\"card-header bg-success text-white\"\u003e\r\n                \u003ch3 class=\"mb-0\"\u003e\u003ci class=\"bi bi-trophy-fill\"\u003e\u003c/i\u003e Top 10 des Menus les Plus Consultés\u003c/h3\u003e\r\n            \u003c/div\u003e\r\n            \u003cdiv class=\"card-body\"\u003e\r\n                \u003cdiv class=\"table-responsive\"\u003e\r\n                    \u003ctable class=\"table table-hover\"\u003e\r\n                        \u003cthead\u003e\r\n                            \u003ctr\u003e\r\n                                \u003cth\u003e#\u003c/th\u003e\r\n                                \u003cth\u003eMenu\u003c/th\u003e\r\n                                \u003cth\u003eConsultations\u003c/th\u003e\r\n                                \u003cth\u003eProgression\u003c/th\u003e\r\n                            \u003c/tr\u003e\r\n                        \u003c/thead\u003e\r\n                        \u003ctbody id=\"topMenusTableBody\"\u003e\r\n                            \u003ctr\u003e\r\n                                \u003ctd colspan=\"4\" class=\"text-center\"\u003e\r\n                                    \u003cdiv class=\"spinner-border text-success\" role=\"status\"\u003e\r\n                                        \u003cspan class=\"visually-hidden\"\u003eChargement...\u003c/span\u003e\r\n                                    \u003c/div\u003e\r\n                                \u003c/td\u003e\r\n                            \u003c/tr\u003e\r\n                        \u003c/tbody\u003e\r\n                    \u003c/table\u003e\r\n                \u003c/div\u003e\r\n            \u003c/div\u003e\r\n        \u003c/div\u003e\r\n\r\n     \r\n        \u003cdiv class=\"text-center mb-5\"\u003e\r\n            \u003cbutton class=\"btn btn-primary btn-lg\" onclick=\"loadStats()\"\u003e\r\n                \u003ci class=\"bi bi-arrow-clockwise\"\u003e\u003c/i\u003e Actualiser les statistiques\r\n            \u003c/button\u003e\r\n        \u003c/div\u003e\r\n    \u003c/div\u003e\r\n\r\n\r\n\u003c/body\u003e\r\n\u003c/html\u003e\r\n",
